SELECT CASE WHEN p.cost >= 690 THEN 'high' WHEN p.cost >= 140 THEN 'mid' ELSE 'low' END AS cost_bucket, MAX(i.quantity) - MIN(i.quantity) AS quantity_range, MAX(i.quantity) AS max_quantity FROM inventory i INNER JOIN products p ON i.product_id = p.id LEFT JOIN stores s ON i.store_id = s.id WHERE i.quantity <= 195 GROUP BY CASE WHEN p.cost >= 690 THEN 'high' WHEN p.cost >= 140 THEN 'mid' ELSE 'low' END ORDER BY quantity_range DESC, cost_bucket DESC;
